import { expect, expectStatus, test } from "../../fixtures";

test.describe("vendor lifecycle", () => {
  test("an admin approves a vendor's w9 extraction from the review queue", { tag: "@LIF-12" }, async ({ factory, apiAs }) => {
    // Arrange
    const { vendor, documents, extractions } = await factory.vendorInReview({ as: "member" });
    const admin = await apiAs("admin");

    // Act
    const queueBefore = await expectStatus<{ vendor_id: string }[]>(await admin.get("/api/review-queue"), 200);
    expect(queueBefore.map((item) => item.vendor_id)).toContain(vendor.id);

    const decision = await admin.post(`/api/extractions/${extractions.w9.id}/decision`, {
      data: { decision: "approve" },
    });
    const decided = await expectStatus<{ id: string; status: string }>(decision, 200);

    // Assert
    expect(decided.status).toBe("approved");
    const stored = await factory.extraction(documents.w9.id, "admin");
    expect(stored.status, "approval is stored, not just echoed").toBe("approved");

    const queueAfter = await expectStatus<{ vendor_id: string }[]>(await admin.get("/api/review-queue"), 200);
    expect(queueAfter.map((item) => item.vendor_id), "vendor still listed in the queue").toContain(vendor.id);
  });
});
